-- Role -> permission assignments, resolved by name (IDs are generated by IDENTITY, never hardcoded).
-- Roles are cumulative: SUPER_ADMIN ⊇ ADMIN ⊇ CLIENT. ADMIN and SUPER_ADMIN can also reserve and
-- pay for vehicles as customers, so they keep every CLIENT permission, including the ":own" ones.

-- CLIENT: customer actions on its own records
INSERT INTO iam.role_permission (role_id, permission_id)
SELECT r.role_id, p.permission_id
FROM iam.role r
CROSS JOIN iam.permission p
WHERE r.name = 'CLIENT'
  AND p.name IN (
      'vehicles:read',
      'reservations:create',
      'reservations:read:own',
      'reservations:update:own',
      'reservations:cancel:own',
      'payments:create:own',
      'invoices:read:own'
  );

-- ADMIN: every CLIENT permission + business operations
INSERT INTO iam.role_permission (role_id, permission_id)
SELECT r.role_id, p.permission_id
FROM iam.role r
CROSS JOIN iam.permission p
WHERE r.name = 'ADMIN'
  AND p.name IN (
      -- as a customer (same as CLIENT)
      'vehicles:read',
      'reservations:create',
      'reservations:read:own',
      'reservations:update:own',
      'reservations:cancel:own',
      'payments:create:own',
      'invoices:read:own',
      -- as a business administrator
      'vehicles:create', 'vehicles:update',
      'branches:manage',
      'maintenance:create', 'maintenance:update',
      'reservations:read', 'reservations:update', 'reservations:cancel',
      'insurance-types:manage',
      'rentals:manage',
      'payments:read', 'payments:review',
      'invoices:read',
      'tracking:read',
      'users:read'
  );

-- SUPER_ADMIN: every permission in the catalog
INSERT INTO iam.role_permission (role_id, permission_id)
SELECT r.role_id, p.permission_id
FROM iam.role r
CROSS JOIN iam.permission p
WHERE r.name = 'SUPER_ADMIN';
